/**
 * K3 implant · W5-T5 · candidate quarantine zone (§4.4.3 landing form E of Decision 5).
 *
 * COMPONENT TRIPLE
 * - Reason to exist : GAP-007 in one sentence — upstream /refine had NO empirical adoption gate,
 *                     so a cheating skill was efficiently refined into the harness. The zone is
 *                     where nominated proposals live while they are still CLAIMS: quarantined
 *                     files under `k3/candidates/`, never harness state, never the main loop.
 * - Axiom binding   : Axiom 9 (adoption clause: the ONLY channel into load-bearing state is the
 *                     empirical selection gate); Axiom 5 (every zone transition is a ledger row
 *                     with trigger/outcome provenance).
 * - Deprecation     : NOT deprecable — without a quarantine there is no difference between
 *                     "proposed" and "adopted", which is exactly the upstream failure shape.
 *
 * TRIGGER-OUTCOME PROVENANCE: every zone event carries the upstream refinement-event syntax
 * ({trigger, changes, evidence, outcome}) so the nomination trail reads in the same grammar as
 * upstream `HarnessRefinementEvent` rows — but lands in the W2 ledger, not in mutable state.
 *
 * MEMORY SPLIT-TRACK (§4.4.8): the "downgrade to memory" verdict writes the D-track (experience
 * judgments) and REFUSES entries without a claim/evidence binding. The B-track (recomputable
 * derivatives) is not this module's concern — it has no gate by design.
 */

import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { RefinementKind, RefinementProposal } from "../../core/refinement/refinement.js";
import type { AppendResult, EventLedger } from "../ledger/event-ledger.js";
import { k3IdemKey } from "../ledger/event-ledger.js";
import type { Allowlist } from "../security/allowlist.js";
import { PROTECTED_DENY_WRITE, pathHasPrefix } from "../security/allowlist.js";
import { contentRef } from "./eval-suite.js";

// ---------------------------------------------------------------------------
// Homes
// ---------------------------------------------------------------------------

/** Agent-nominatable (k3.submit_candidate declares this prefix); NOT deny-write by design. */
export const CANDIDATES_HOME = "k3/candidates";
/** Immutable archive of every accepted variant — deny-write (W1 allowlist literal). */
export const ARCHIVE_HOME = "k3/archive";
/** The active pointer's home — deny-write for the agent domain (§4.4.3 constraint 3). */
export const ACTIVE_HOME = "active";
/** D-track memory (experience judgments; evidence-bound, gated). */
export const MEMORY_D_HOME = "k3/memory_d";

export class CandidateZoneError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "CandidateZoneError";
	}
}

export class EvidenceBindingError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "EvidenceBindingError";
	}
}

// ---------------------------------------------------------------------------
// Records
// ---------------------------------------------------------------------------

/** Upstream refinement-event grammar, reused as the provenance syntax (§4.4.3 留痕语法). */
export interface TriggerOutcomeTrace {
	/** What prompted the nomination (turn id, auto-refine reason, explicit instruction). */
	readonly trigger: string;
	/** Edit summaries (one line per proposed edit). */
	readonly changes: readonly string[];
	/** Evidence pointer(s) — ledger event ids / evidence ids, never free prose only. */
	readonly evidence: string;
	readonly outcome: "nominated" | "rejected" | "downgraded_memory";
}

export interface CandidateRecord {
	readonly cand_id: string;
	readonly kind: RefinementKind;
	readonly proposal: RefinementProposal;
	/** Where the proposal came from (session/trajectory reference — an opaque ref, not the text). */
	readonly source_trace: string;
	readonly trace: TriggerOutcomeTrace;
	/** Rollback lineage when the proposal reverts an earlier refinement. */
	readonly rollback_of?: string;
	readonly funnel_level: "F0";
	readonly created_at: string;
}

export interface DTrackEntry {
	readonly entry_id: string;
	readonly content: string;
	/** Mandatory bindings (§4.4.8: 未绑定证据的经验条目一律拒收). */
	readonly claim_id: string;
	readonly evidence_ids: readonly string[];
	readonly created_at: string;
}

// ---------------------------------------------------------------------------
// Zone
// ---------------------------------------------------------------------------

export interface CandidateZoneOptions {
	/** Filesystem root the homes hang off (repo root in production, tmp dir in tests). */
	readonly root: string;
	readonly ledger: EventLedger;
	readonly phase: string;
	/** W1 allowlist; when given, the zone verifies active/ and arch

