}

// ---------------------------------------------------------------------------
// Zone
// ---------------------------------------------------------------------------

export interface CandidateZoneOptions {
	/** Filesystem root the homes hang off (repo root in production, tmp dir in tests). */
	readonly root: string;
	readonly ledger: EventLedger;
	readonly phase: string;
	/** W1 allowlist; when given, the zone verifies active/ and archive stay agent-deny-write. */
	readonly allowlist?: Allowlist;
	readonly now?: () => number;
}

/**
 * The quarantine. Candidates enter here (and ONLY here) from the planning phase; nothing in this
 * class can write harness state, the active pointer, or the archive — promotion is a different
 * module with a different authority (deterministic program + dual-sign, §4.4.3 constraint 2).
 */
export class CandidateZone {
	private readonly root: string;
	private readonly ledger: EventLedger;
	private readonly phase: string;
	private readonly now: () => number;
	private seq = 0;

	constructor(options: CandidateZoneOptions) {
		this.root = options.root;
		this.ledger = options.ledger;
		this.phase = options.phase;
		this.now = options.now ?? Date.now;
		// Declaration = enforcement: the zone refuses to exist in a world where the agent could
		// write the archive or the active pointer directly (the quarantine would be theatre).
		for (const home of [ARCHIVE_HOME, ACTIVE_HOME]) {
			if (!PROTECTED_DENY_WRITE.some((p) => pathHasPrefix(home, p))) {
				throw new CandidateZoneError(
					`${home} is not covered by PROTECTED_DENY_WRITE (${PROTECTED_DENY_WRITE.join(", ")}); ` +
						`a quarantine next to an agent-writable activation surface is not a quarantine`,
				);
			}
			if (options.allowlist) {
				const decision = options.allowlist.checkPath(home, "write", this.root);
				if (decision.allowed) {
					throw new CandidateZoneError(
						`allowlist grants agent-domain write on ${home}; refusing to install the candidate zone ` +
							`until the enforcement surface matches the declaration surface`,
					);
				}
			}
		}
		mkdirSync(join(this.root, CANDIDATES_HOME), { recursive: true });
		mkdirSync(join(this.root, MEMORY_D_HOME), { recursive: true });
	}

	get candidatesDir(): string {
		return join(this.root, CANDIDATES_HOME);
	}

	/**
	 * ADMIT verdict: the planning-phase nomination path. Writes `k3/candidates/<cand_id>/` (the
	 * proposal + provenance as immutable JSON) and one idempotent `cand.create` ledger row. The
	 * candidate does NOT enter harness state and does NOT run in the main loop.
	 */
	nominate(input: {
		readonly proposal: RefinementProposal;
		readonly kind: RefinementKind;
		readonly trigger: string;
		readonly sourceTrace: string;
		readonly evidence: string;
		readonly rollbackOf?: string;
	}): { record: CandidateRecord; appended: AppendResult } {
		const bodyRef = contentRef(input.proposal);
		const candId = `cand_${bodyRef.slice(3, 15)}_${++this.seq}`;
		const trace: TriggerOutcomeTrace = {
			trigger: input.trigger,
			changes: input.proposal.edits.map((e) => `${e.action} ${e.kind} ${e.id ?? e.title ?? "(new)"}`),
			evidence: input.evidence,
			outcome: "nominated",
		};
		const record: CandidateRecord = {
			cand_id: candId,
			kind: input.kind,
			proposal: input.proposal,
			source_trace: input.sourceTrace,
			trace,
			...(input.rollbackOf === undefined ? {} : { rollback_of: input.rollbackOf }),
			funnel_level: "F0",
			created_at: new Date(this.now()).toISOString(),
		};
		const dir = join(this.candidatesDir, candId);
		mkdirSync(dir, { recursive: true });
		writeFileSync(join(dir, "candidate.json"), `${JSON.stringify(record, null, "\t")}\n`);
		const appended = this.ledger.append({
			event_type: "cand.create",
			actor: { role: "harness" },
			action: "nominate",
			phase: this.phase,
			payload: { cand_id: candId, kind: input.kind, ...trace, source_trace: input.sourceTrace },
			idem_key: k3IdemKey("refine", this.phase, { intent: "nominate", body_ref: bodyRef }),
		});
		return { record, appended };
	}

	/**
	 * REJECT verdict: a `cand.create{outcome:"rejected"}` ledger row with a structured reason —
	 * and NO file (§4.4.3: 驳回 → 不落盘). The trail exists; the artifact does not.
	 */
	reject(proposal: RefinementProposal, trigger: string, reasonCode: string, detail: string): AppendResult {
		return this.ledger.append({
			event_type: "cand.create",
			actor: { role: "harness" },
			action: "reject",
			phase: this.phase,
			payload: {
				kind: "rejected_proposal",
				trigger,
				changes: proposal.edits.map((e) => `${e.action} ${e.kind} ${e.id ?? e.t

