c(join(dir, "candidate.json"), `${JSON.stringify(record, null, "\t")}\n`);
		const appended = this.ledger.append({
			event_type: "cand.create",
			actor: { role: "harness" },
			action: "nominate",
			phase: this.phase,
			payload: { cand_id: candId, kind: input.kind, ...trace, source_trace: input.sourceTrace },
			idem_key: k3IdemKey("refine", this.phase, { intent: "nominate", body_ref: bodyRef }),
		});
		return { record, appended };
	}

	/**
	 * REJECT verdict: a `cand.create{outcome:"rejected"}` ledger row with a structured reason —
	 * and NO file (§4.4.3: 驳回 → 不落盘). The trail exists; the artifact does not.
	 */
	reject(proposal: RefinementProposal, trigger: string, reasonCode: string, detail: string): AppendResult {
		return this.ledger.append({
			event_type: "cand.create",
			actor: { role: "harness" },
			action: "reject",
			phase: this.phase,
			payload: {
				kind: "rejected_proposal",
				trigger,
				changes: proposal.edits.map((e) => `${e.action} ${e.kind} ${e.id ?? e.title ?? "(new)"}`),
				evidence: detail,
				outcome: "rejected",
				reason_code: reasonCode,
			},
			idem_key: k3IdemKey("refine", this.phase, { intent: "reject", body_ref: contentRef(proposal) }),
		});
	}

	/**
	 * DOWNGRADE verdict: the proposal survives only as a D-track memory entry — an experience
	 * judgment that MUST carry a claim/evidence binding (§4.4.8). Unbound entries are refused
	 * outright: this throw is the "未绑定证据的经验条目一律拒收" clause in executable form.
	 */
	downgradeToMemory(input: {
		readonly content: string;
		readonly claimId: string | undefined;
		readonly evidenceIds: readonly string[];
		readonly trigger: string;
	}): { entry: DTrackEntry; appended: AppendResult } {
		if (input.claimId === undefined || input.claimId.length === 0 || input.evidenceIds.length === 0) {
			throw new EvidenceBindingError(
				"D-track memory requires claim_id + evidence_ids (§4.4.8); an experience judgment without " +
					"evidence binding is refused — ACE's -3.4 net harm is the measured cost of skipping this",
			);
		}
		const entry: DTrackEntry = {
			entry_id: `dmem_${contentRef(input.content).slice(3, 15)}`,
			content: input.content,
			claim_id: input.claimId,
			evidence_ids: input.evidenceIds,
			created_at: new Date(this.now()).toISOString(),
		};
		writeFileSync(join(this.root, MEMORY_D_HOME, `${entry.entry_id}.json`), `${JSON.stringify(entry, null, "\t")}\n`);
		const appended = this.ledger.append({
			event_type: "cand.create",
			actor: { role: "harness" },
			action: "downgrade",
			phase: this.phase,
			payload: {
				entry_id: entry.entry_id,
				trigger: input.trigger,
				changes: [],
				evidence: input.evidenceIds.join(","),
				outcome: "downgraded_memory",
				claim_id: input.claimId,
			},
			idem_key: k3IdemKey("refine", this.phase, { intent: "downgrade", body_ref: contentRef(input.content) }),
		});
		return { entry, appended };
	}

	get(candId: string): CandidateRecord {
		const path = join(this.candidatesDir, candId, "candidate.json");
		if (!existsSync(path)) throw new CandidateZoneError(`candidate ${candId} not found in the zone`);
		return JSON.parse(readFileSync(path, "utf8")) as CandidateRecord;
	}

	list(): string[] {
		if (!existsSync(this.candidatesDir)) return [];
		return readdirSync(this.candidatesDir, { withFileTypes: true })
			.filter((e) => e.isDirectory())
			.map((e) => e.name)
			.sort();
	}

	/**
	 * The main loop's view of adoptable state: ONLY what the active pointer names. Candidates are
	 * structurally invisible here — this method never reads `k3/candidates/` at all, so "候选不参
	 * 与主回路执行" is a property of the code shape, not a promise.
	 */
	mainLoopView(): { active_ptr: string | null } {
		const ptrPath = join(this.root, ACTIVE_HOME, "pointer.json");
		if (!existsSync(ptrPath)) return { active_ptr: null };
		const ptr = JSON.parse(readFileSync(ptrPath, "utf8")) as { target?: string };
		return { active_ptr: ptr.target ?? null };
	}

	/** Quarantine assertion: the candidate exists in the zone and is NOT the active target. */
	assertQuarantined(candId: string): void {
		this.get(candId); // throws if absent
		const view = this.mainLoopView();
		if (view.active_ptr === candId) {
			throw new CandidateZoneError(
				`candidate ${candId} is the ACTIVE pointer target while still zoned; ` +
					`a candidate reachable from the main loop is not quarantined`,
			);
		}
	}
}

