/**
 * K3 implant · W5-T5 · three-tier eval suites + FCQ (Feedback Channel Quality) freeze.
 *
 * COMPONENT TRIPLE
 * - Reason to exist : adaptive querying of one eval set manufactures Θ(√(k/n)) phantom gains
 *                     (§4.4.10 row "三层 eval 套件"); the gate's evidence is only as good as the
 *                     channel it flows through, so channel quality itself must be a mechanical,
 *                     no-LLM quantity (G11) with a freeze semantics.
 * - Axiom binding   : Axiom 6 (statistics over anecdotes: Thresholdout coarse feedback, sample
 *                     floors); Axiom 9 (G11: no reliable feedback → self-improvement freezes).
 * - Deprecation     : the sealed suite may drop to spot checks if its upkeep exceeds 20% of the
 *                     eval budget (G10 clause) but is NEVER removed; the FCQ four-subquantity
 *                     set is FROZEN (literal constant, no dynamic injection) — changing it is a
 *                     source change that must survive `make verify` and the W4 invariants.
 *
 * THREE SUITES (§4.4.4 holdout discipline, Dwork Thresholdout ledgered):
 *   dev    — generator-visible, unlimited queries, exact scores, NOT ledgered;
 *   gated  — generator-invisible, every evaluation is one `holdout.query` ledger row, feedback
 *            is COARSE (pass / fail / marginal), exact scores go to the ledger only;
 *   sealed — invisible to the whole optimisation process, query budget HARDCODED; exceeding it
 *            forces HOLD + suite rotation. Exact scores never return to the generator.
 */

import { createHash } from "node:crypto";
import type { CalibrationReport, SeededDefect } from "../canary/guid-sentinel.js";
import { calibrate } from "../canary/guid-sentinel.js";
import type { L2Reviewer, L2ReviewOutcome, ReviewInput } from "../gate/review.js";
import { assertContextFree } from "../gate/review.js";
import type { AppendResult, EventLedger } from "../ledger/event-ledger.js";

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

export class SuiteBudgetError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "SuiteBudgetError";
	}
}

export class HomogeneousReviewError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "HomogeneousReviewError";
