/** Composite utility (§4.4.5, SICA form): U = 0.5·score + 0.25·cost + 0.25·time − timeout penalty. */
export function compositeUtility(parts: {
	readonly score: number;
	readonly costScore: number;
	readonly timeScore: number;
	readonly timeoutPenalty?: number;
	/** G14 deprecation clause: early exploration may use the performance term only. */
	readonly exploreEarly?: boolean;
}): number {
	if (parts.exploreEarly === true) return parts.score - (parts.timeoutPenalty ?? 0);
	return 0.5 * parts.score + 0.25 * parts.costScore + 0.25 * parts.timeScore - (parts.timeoutPenalty ?? 0);
}

// ---------------------------------------------------------------------------
// eval-1 · regression on HELD-OUT golden cases (real runs, not self-reports)
// ---------------------------------------------------------------------------

export interface GoldenCase {
	readonly case_id: string;
	/** Held-out flag: eval-1 refuses cases the generator could query freely. */
	readonly held_out: boolean;
}

export interface RegressionReport {
	readonly green: boolean;
	readonly passed: readonly string[];
	readonly failed: readonly string[];
	readonly total: number;
}

/**
 * eval-1: runs every held-out golden case through the injected runner (a REAL execution — the
 * runner's boolean is the measured outcome, never the candidate's claim). A non-held-out case in
 * the list is a suite-discipline violation and throws.
 */
export function evalTier1Regression(
	cases: readonly GoldenCase[],
	runner: (caseId: string) => boolean,
): RegressionReport {
	const leaked = cases.filter((c) => !c.held_out);
	if (leaked.length > 0) {
		throw new SuiteBudgetError(
			`eval-1 received ${leaked.length} non-held-out case(s) (${leaked.map((c) => c.case_id).join(", ")}); ` +
				`regression verdicts on generator-visible cases measure memorisation, not quality (G16)`,
		);
	}
	const passed: string[] = [];
	const failed: string[] = [];
	for (const c of cases) (runner(c.case_id) ? passed : failed).push(c.case_id);
	return { green: failed.length === 0, passed, failed, total: cases.length };
}

// ---------------------------------------------------------------------------
// eval-2 · heterogeneous review (context-free subagent, builder ≠ checker)
// ---------------------------------------------------------------------------

export interface ReviewLineage {
	/** Stable lineage id, e.g. "builder@sessionA" / "k3-review-subagent@1". */
	readonly lineage: string;
}

/**
 * eval-2: the W3 context-free reviewer with an EXTRA structural check — the reviewer lineage must
 * differ from the builder lineage (§4.4.2 "评审段的独立性"; same-session self-review is an
