export interface CanaryCalibrationOutcome {
	readonly report: CalibrationReport;
	/** Verifier health = the LOWER of the two per-source detection rates (§4.4.7 row 1). */
	readonly verifier_health: number;
}

/**
 * eval-3: runs the W4 calibration (both injection sources mandatory, rates never merged) and
 * derives the FCQ `verifier_health` input as the lower of the two per-source rates.
 */
export function evalTier3Canary(
	ledger: EventLedger,
	phase: string,
	defects: readonly SeededDefect[],
	floor = 0.8, // PROVISIONAL: 待 GAP-058 标定
): CanaryCalibrationOutcome {
	const report = calibrate(ledger, phase, defects, floor);
	const verifierHealth = Math.min(...report.rates.map((r) => r.rate));
	return { report, verifier_health: verifierHealth };
}

// ---------------------------------------------------------------------------
// FCQ · Feedback Channel Quality (§4.4.7) — four subquantities, FROZEN set
// ---------------------------------------------------------------------------

/**
 * The FCQ subquantity set is FROZEN: a literal constant with exactly these four members, no
 * config read, no env read, no runtime extension point. The k3-selection-gate test asserts the
 * shape; extending it is a source change that must survive `make verify`.
 */
export const FCQ_SUBQUANTITIES = Object.freeze([
	"fcq.verifier_health",
	"fcq.ground_truth_coverage",
	"fcq.holdout_budget",
	"fcq.suite_discrimination",
] as const);

export type FcqSubquantity = (typeof FCQ_SUBQUANTITIES)[number];

/** Freeze thresholds (§4.4.7 table). */
export const FCQ_FREEZE_THRESHOLDS = Object.freeze({
	verifierHealthFloor: 0.8, // PROVISIONAL: 待 GAP-058 标定
	groundTruthCoverageFloor: 0.5, // PROVISIONAL: 待 GAP-058 标定
	/** = 0 → frozen AND suite rotation required (hard, not provisional: an empty budget is empty). */
	holdoutBudgetFloor: 0,
	suiteDiscriminationFloor: 0.05, // PROVISIONAL: 待 GAP-058 标定（饱和线）
});

export interface FcqInputs {
	/** Domain the reading applies to — freezing is PER-DOMAIN independent (§4.4.7 分域差异). */
	readonly domain: string;
	/** Lower of the two per-source detection rates from the latest L4 calibration. */
	readonly verifierHealth: number;
	/** Share of this domain's candidates with a hard verifier available. */
	readonly groundTruthCoverage: number;
	/** Remaining sealed-suite query budget. */
	readonly holdoutBudgetRemaining: number;
	/** Gated-suite discrimination (verdict flip rate + score variance, folded by the caller). */
	readonly suiteDiscrimination: number;
}

export interface FcqReading {
	readonly domain: string;
	readonly frozen: boolean;
	/** Which subquantities crossed their freeze threshold. */
	readonly breached: readonly FcqSubquantity[];
	readonly values: Readonly<Record<FcqSubquantity, number>>;
}

/**
 * MECHANICAL FCQ (no LLM anywhere on this path): the conjunction of the four subquantities.
 * A single breach freezes the domain. Freezing is a CONDITION, not a configuration — recompute
 * with recovered inputs and the domain unfreezes (the ledger row is written by the caller via
 * `ledgerFcqTransition`).
 */
export function computeFcq(inputs: FcqInputs): FcqReading {
	const t = FCQ_FREEZE_THRESHOLDS;
	const breached: FcqSubquantity[] = [];
	if (inputs.verifierHealth < t.verifierHealthFloor) breached.push("fcq.verifier_health");
	if (inputs.groundTruthCoverage < t.groundTruthCoverageFloor) breached.push("fcq.ground_truth_coverage");
	if (inputs.holdoutBudgetRemaining <= t.holdoutBudgetFloor) breached.push("fcq.holdout_budget");
	if (inputs.suiteDiscrimination < t.suite

DiscriminationFloor) breached.push("fcq.suite_discrimination");
	return {
		domain: inputs.domain,
		frozen: breached.length > 0,
		breached,
		values: {
			"fcq.verifier_health": inputs.verifierHealth,
			"fcq.ground_truth_coverage": inputs.groundTruthCoverage,
			"fcq.holdout_budget": inputs.holdoutBudgetRemaining,
			"fcq.suite_discrimination": inputs.suiteDiscrimination,
		},
	};
}

/** A reading provider — the seam funnel/promotion consume; per-domain independent. */
export type FcqProvider = (domain: string) => FcqReading;

export class FcqShapeError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "FcqShapeError";
	}
}

/**
 * FCQ FOUR-SUBQUANTITY FREEZE, executable form: exactly these four members in this order, both
 * literals deep-frozen. Called at install time — a runtime that managed to extend or reorder the
 * set refuses to arm the selection gate (G11 is only as strong as the quantity it reads).
 */
export function assertFcqShapeFrozen(): void {
	const expected: readonly string[] = [
		"fcq.verifier_health",
		"fcq.ground_truth_coverage",
		"fcq.holdout_budget",
		"fcq.suite_discrimination",
	];
	const actual: readonly string[] = FCQ_SUBQUANTITIES;
	if (
		actual.length !== expected.length ||
		expected.some((e, i) => actual[i] !== e) ||
		!Object.isFrozen(FCQ_SUBQUANTITIES) ||
		!Object.isFrozen(FCQ_FREEZE_THRESHOLDS)
	) {
		throw new FcqShapeError(
			`FCQ subquantity set has been tampered with (got [${actual.join(", ")}]); the four-member set ` +
				`is FROZEN (§4.4.7) and changing it is a source change, not a runtime operation`,
		);
	}
}

/**
 * Ledgers a freeze/unfreeze TRANSITION (both directions are auditable events, §4.4.7 "解冻同样
 * 入账本"). Returns null when there is no transition (steady state is not an event).
 */
export function ledgerFcqTransition(
	ledger: EventLedger,
	phase: string,
	previous: FcqReading | undefined,
	current: FcqReading,
): AppendResult | null {
	const was = previous?.frozen ?? false;
	if (was === current.frozen) return null;
	return ledger.append({
		event_type: current.frozen ? "selection.freeze" : "selection.unfreeze",
		actor: { role: "harness" },
		action: current.frozen ? "freeze" : "unfreeze",
		phase,
		payload: {
			domain: current.domain,
			reason_code: current.frozen ? "G11_FEEDBACK_FROZEN" : "G11_FEEDBACK_RECOVERED",
			breached: current.breached,
			values: current.values,
		},
		idem_key: null,
	});
}

