		if (widening) {
			this.ledger.append({
				event_type: "selection.gaming_suspected",
				actor: { role: "harness" },
				action: "alarm",
				phase: this.phase,
				payload: { gap_series_tail: this.gapSeries.slice(-3), reason_code: "SUITE_GAP_WIDENING" },
