// ---------------------------------------------------------------------------
// F2 · holdout (statistics + guardrail conjunction + critical/canary veto)
// ---------------------------------------------------------------------------

export interface GuardrailReading {
	readonly name: string;
	readonly breached: boolean;
	/** Critical guardrails carry the G5 one-vote veto. */
	readonly critical: boolean;
}

export interface F2Inputs {
	readonly candId: string;
	/** Per-instance primary-metric scores on the GATED holdout suite. */
	readonly candidateScores: readonly number[];
	readonly baselineScores: readonly number[];
	readonly guardrails: readonly GuardrailReading[];
	/** From the W4 apparatus (canary_triggered ∈ CRITICAL_METRICS). */
	readonly canaryTriggered: boolean;
	/** Coarse threshold for the Thresholdout signal on this suite. */
	readonly passThreshold: number;
}

export interface F2Outcome extends LevelOutcome {
	readonly stats: MannWhitneyResult | null;
}

/**
 * F2 with the §4.4.5 statistical criteria. Consumes ONE gated-suite query (ledgered as
 * `holdout.query` by the suite manager). Order of the vetoes: sample floor (HOLD — unevaluable
 * is not a failure) → critical/canary/guardrail (REJECT, one vote suffices) → significance+MDE.
 */
export function runF2Holdout(inputs: F2Inputs, suites: EvalSuiteManager): F2Outcome {
	if (inputs.candidateScores.length < F2_SAMPLE_FLOOR || inputs.baselineScores.length < F2_SAMPLE_FLOOR) {
		return {
			level: "F2",
			verdict: "HOLD",
			reason_codes: ["F2_SAMPLE_FLOOR_UNMET"],
			detail: `n=(${inputs.candidateScores.length},${inputs.baselineScores.length}) < floor ${F2_SAMPLE_FLOOR}; HOLD, never PASS`,
			stats: null,
		};
	}
	const codes: string[] = [];
	if (inputs.canaryTriggered) codes.push("F2_CANARY_TRIGGERED");
	for (const g of inputs.guardrails) {
		if (g.breached)
			codes.push(g.critical ? `F2_CRITICAL_${g.name.toUpperCase()}` : `F2_GUARDRAIL_${g.name.toUpperCase()}`);
	}
	const stats = mannWhitneyU(inputs.candidateScores, inputs.baselineScores);
	const mean = inputs.candidateScores.reduce((a, b) => a + b, 0) / inputs.candidateScores.length;
	suites.queryGated(inputs.candId, mean, inputs.passThreshold);
	if (codes.length > 0) {
		return { level: "F2", verdict: "REJECT", reason_codes: codes, detail: "guardrail/critical/canary veto", stats };
	}
	if (stats.p >= F2_ALPHA || stats.effect < F2_MDE) {
		return {
			level: "F2",
			verdict: "REJECT",
			reason_codes: ["F2_NOT_SIGNIFICANT"],
			detail: `p=${stats.p.toFixed(4)} (α=${F2_ALPHA}), effect=${stats.effect.toFixed(3)} (MDE=${F2_MDE})`,
			stats,
		};
	}
	return {
		level: "F2",
		verdict: "PASS",
		reason_codes: [],
		detail: "significant improvement, guardrails intact",
		stats,
	};
}

