export function runF3Promotion(inputs: F3Inputs): LevelOutcome {
	if (inputs.f2.verdict !== "PASS") {
		return {
			level: "F3",
			verdict: "REJECT",
			reason_codes: ["F3_F2_NOT_PASSED"],
			detail: "monotone funnel: F3 is unreachable without an F2 PASS",
		};
	}
	const codes: string[] = [];
	if (!inputs.refutation.attempted) codes.push("F3_REFUTATION_NOT_ATTEMPTED");
	else if (!inputs.refutation.survived) codes.push("F3_REFUTED");
