	if (inputs.passAtKDelta > 0 && inputs.passAt1Delta <= 0) {
		return {
			level: "F3",
			verdict: "RECYCLE",
			reason_codes: [...codes, "F3_RESAMPLING_EFFECT"],
			detail: `pass@k Δ=${inputs.passAtKDelta} with pass@1 Δ=${inputs.passAt1Delta}: matched-budget resampling explains it`,
		};
	}
	if (!inputs.dualSign.kernel || !inputs.dualSign.human) codes.push("F3_DUAL_SIGN_INCOMPLETE");
	return codes.length === 0
		? { level: "F3", verdict: "PASS", reason_codes: [], detail: "refutation survived, G15 complete, dual-signed" }
		: { level: "F3", verdict: "REJECT", reason_codes: codes, detail: `missing G15: ${missing.join(",") || "none"}` };
