	readonly currentTurn: () => number;
}

/**
 * The A-phase admission check. Order matters: quota and gate preconditions produce DENY (the
 * request never reaches planning); a G11 freeze produces HOLD-FROZEN, which still allows
 * planning (shadow accumulation into the zone) but marks that the pointer will not move —
 * "冻结的是合入，不是运行" (§4.4.7).
 */
export function createRefineEntryGate(deps: RefineEntryDeps): (payload: Record<string, unknown>) => EntryVerdict {
	let lastAdmittedTurn: number | null = null;
	return (payload: Record<string, unknown>): EntryVerdict => {
		const ledgerEntry = (verdict: EntryVerdict): EntryVerdict => {
			deps.ledger.append({
				event_type: "selection.entry",
				actor: { role: "gatekeeper" },
				action: verdict.status === "DENY" ? "deny" : "admit",
				phase: deps.phase,
				payload: {
					status: verdict.status,
					planning_allowed: verdict.planning_allowed,
					merge_allowed: verdict.merge_allowed,
					reason_code: verdict.reason_code,
					domain: deps.domain,
					instructions_present: typeof payload.instructions === "string",
				},
				idem_key: null,
			});
			return verdict;
		};

		if (!deps.phaseGatePassed()) {
			return ledgerEntry({
				status: "DENY",
				planning_allowed: false,
				merge_allowed: false,
				reason_code: "REFINE_BEFORE_PHASE_GATE",
			});
		}
		const turn = deps.currentTurn();
		if (lastAdmittedTurn !== null && lastAdmittedTurn === turn) {
			return ledgerEntry({
				status: "DENY",
				planning_allowed: false,
				merge_allowed: false,
				reason_code: "REFINE_QUOTA_ONCE_PER_TURN",
			});
		}
		const reading = deps.fcq(deps.domain);
		if (reading.frozen) {
			lastAdmittedTurn = turn;
			return ledgerEntry({
				status: "HOLD-FROZEN",
				planning_allowed: true, // shadow accumulation: candidates still land in the zone
				merge_allowed: false, // the pointer NEVER moves while frozen
				reason_code: "G11_FEEDBACK_FROZEN",
			});
		}
		lastAdmittedTurn = turn;
		return ledgerEntry({ status: "ADMIT", planning_allowed: true, merge_allowed: false, reason_code: null });
	};
}

export interface InterceptRefineOptions {
	readonly entryGate: (payload: Record<string, unknown>) => EntryVerdict;
	/** W1 boundary — the wrapped handlers stay domain-guarded (I3: every registration is guarded). */
