 * the K3 entry gate, re-guarding them through the W1 domain proxy so the guard mark survives the
 * wrap. `refine.status` passes through untouched (read-only surface); `refine.run` consults the
 * entry gate first — DENY throws before the upstream handler is reached.
 */
export function interceptRefineHandlers(
	handlers: HostRequestHandlers,
	options: InterceptRefineOptions,
): HostRequestHandlers {
	const upstreamRun = handlers["refine.run"];
	const upstreamStatus = handlers["refine.status"];
	if (upstreamRun === undefined || upstreamStatus === undefined) {
		throw new RefineEntryDeniedError(
			"refine.run / refine.status not present in the handler table; the entry gate has nothing to cover " +
				"and refusing is safer than silently covering a partial surface",
			"REFINE_SURFACE_INCOMPLETE",
		);
	}
	const gatedRun: HostRequestHandler = async (payload) => {
		const verdict = options.entryGate(payload);
		if (verdict.status === "DENY") {
			throw new RefineEntryDeniedError(
				`refine.run denied by the K3 entry gate: ${verdict.reason_code}`,
				verdict.reason_code ?? "REFINE_DENIED",
			);
		}
		const upstream = await upstreamRun(payload);
		// The verdict rides along so callers can see HOLD-FROZEN without a second gate query.
		return { ...upstream, k3_entry_status: verdict.status, k3_merge_allowed: verdict.merge_allowed };
	};
	return {
		...handlers,
		"refine.run": withDomainGuard("refine.run", gatedRun, DOMAIN_REGISTRY["refine.run"], options.boundary),
		"refine.status": withDomainGuard(
			"refine.status",
			upstreamStatus,
			DOMAIN_REGISTRY["refine.status"],
			options.boundary,
		),
	};
}

