/**
 * The K3 replacement for the upstream apply step. THE APPLY PHASE IS DISABLED: no edit reaches
 * harness state, no file under the harness's control changes, and the function PROVES it by
 * snapshotting the state JSON before routing and comparing after — a mutation is a thrown
 * `StateMutationError`, not a logged warning. Planning survives as the NOMINATION mechanism:
 * an admitted plan becomes a quarantined candidate with full trigger-outcome provenance.
 */
export function quarantineInsteadOfApply(
	state: HarnessState,
	plan: RefinementPlan,
	triage: TriageVerdict,
	zone: CandidateZone,
	trigger: string,
): K3ApplyOutcome {
	const before = JSON.stringify(state);
	let outcome: K3ApplyOutcome;
	if (triage.verdict === "admit") {
		const { record } = zone.nominate({
			proposal: plan.proposal,
			kind: triage.kind,
			trigger,
			sourceTrace: `refinement_plan:${plan.id}`,
			evidence: triage.evidence,
			...(plan.rollbackOf === undefined ? {} : { rollbackOf: plan.rollbackOf }),
		});
		outcome = { state, outcome: "nominated", candidate: record, memory_entry: null };
	} else if (triage.verdict === "reject") {
		zone.reject(plan.proposal, trigger, triage.reason_code, triage.detail);
		outcome = { state, outcome: "rejected", candidate: null, memory_entry: null };
	} else {
		const { entry } = zone.downgradeToMemory({
			content: triage.content,
			claimId: triage.claimId,
			evidenceIds: triage.evidenceIds,
			trigger,
		});
		outcome = { state, outcome: "downgraded_memory", candidate: null, memory_entry: entry };
	}
	if (JSON.stringify(state) !== before) {
		throw new StateMutationError(
			"the K3 routing mutated harness state — the apply phase is DISABLED and this path must be " +
				"side-effect-free on live state (G12 / §4.4.3 constraint 1); refusing to continue",
		);
	}
	return outcome;
}

