/**
 * The complete set of legal push targets — exactly the four §4.1.9 effort abstractions. There
 * is no "write_more", no "longer_answer", no "more_detail": the push object is an evidence
 * action, never text volume.
 */
export const EVIDENCE_ACTION_TARGETS: readonly string[] = EFFORT_EVENT_TYPES;

export class NonEvidencePushError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "NonEvidencePushError";
	}
}

/** Declaration = enforcement: a push targeting anything but an evidence action is refused. */
export function assertEvidenceTarget(target: string): void {
	if (!EVIDENCE_ACTION_TARGETS.includes(target)) {
		throw new NonEvidencePushError(
			`push target "${target}" is not an evidence action (${EVIDENCE_ACTION_TARGETS.join(", ")}) — ` +
				"pushes act on evidence actions, never on text volume",
		);
	}
}

