// ---------------------------------------------------------------------------

/** Maximum pushes per boundary at verifier strength 1.0. PROVISIONAL: 待 GAP-058 标定 */
export const MAX_PUSHES_PER_BOUNDARY = 4;

/**
 * Verifier strength for a domain, from a W4 calibration report: the LOWEST per-source detection
 * rate (the chain is only as strong as its weakest injection source — same "take the lower"
 * discipline as W5's eval-3). No calibration rows → strength 0 → zero pressure.
 */
export function verifierStrengthFromCalibration(report: CalibrationReport): number {
	if (report.rates.length === 0) return 0;
	let min = 1;
	for (const r of report.rates) if (r.rate < min) min = r.rate;
	return min;
}

/**
 * The ceiling: how many pushes a boundary may carry in a domain, proportional to that domain's
 * measured verifier strength. Strength 0 → ceiling 0 (no verifier, no pressure); strength 1 →
 * the full provisional maximum. Monotone by construction.
 */
export function domainPressureCeiling(verifierStrength: number): number {
	const s = Math.min(1, Math.max(0, verifierStrength));
	return Math.floor(MAX_PUSHES_PER_BOUNDARY * s);
}

/** Pressure for one obligation: zero when it is closed, ceiling-bounded when open. */
export function pressureFor(obligation: Obligation, verifierStrength: number): number {
	if (obligation.closed) return 0;
	return domainPressureCeiling(verifierStrength) > 0 ? 1 : 0;
}

