export interface SteeringInputs {
	readonly ledgerDir: string;
	readonly phase: string;
	/** Metered effort (from EffortContract.meter — ledger-derived, self-report excluded). */
	readonly metered: MeteredEffort;
	readonly floors: ExtensiveFloors;
	readonly obligations: readonly Obligation[];
	/** Measured verifier strength for the phase's domain (W4 calibration). */
	readonly verifierStrength: number;
}

/**
 * The steering wheel. Reads the metered deficits against the declared floors and produces
 * boundary pushes:
 *
 *  1. a premature topic switch (unclosed obligations) steers BACK to those obligations —
 *     never into longer thinking;
 *  2. floor deficits become evidence-action pushes (retrieve / read / enumerate / verify),
 *     but ONLY while open obligations remain — closed obligations get no pressure, and a
 *     phase whose obligations are all discharged gets no pushes no matter what the meters say;
 *  3. everything is capped by the domain ceiling: weak verifiers, little pressure; no
 *     verifier, no pressure at all.
 *
 * Every push it emits targets an evidence action and rides the turn boundary (Decision 8:
 * control-flow steering is a turn-boundary intervention).
 */
export function steeringPushes(inputs: SteeringInputs): Push[] {
	const ceiling = domainPressureCeiling(inputs.verifierStrength);
	if (ceiling === 0) return [];

	const open = inputs.obligations.filter((o) => !o.closed);
	const pushes: Push[] = [];

	// 1 · premature-switch correction first: return to unclosed obligations.
	const finding = detectPrematureSwitch(inputs.ledgerDir, inputs.phase);
	const correction = interveneOnPrematureSwitch(finding);
	if (correction !== null) pushes.push(correction);

	// 2 · floor deficits → evidence-action pushes, only against OPEN obligations.
	if (open.length > 0) {
		const deficits: { target: string; reason: string }[] = [];
		if (inputs.metered.retrievals < inputs.floors.retrievalMin) {
			deficits.push({
				target: "effort.retrieval",
				reason: `retrievals ${inputs.metered.retrievals} < floor ${inputs.floors.retrievalMin}`,
			});
		}
		const fulltext = inputs.metered.readingNotes.fulltext ?? 0;
		if (fulltext < inputs.floors.fulltextNotesMin) {
			deficits.push({
				target: "effort.reading_note",
				reason: `fulltext notes ${fulltext} < floor ${inputs.floors.fulltextNotesMin} (depth types never substitute)`,
			});
		}
		const underEnumerated = Object.entries(inputs.metered.alternativesByDecision).filter(
			([, n]) => n < inputs.floors.alternativesPerDecision,
		);
		if (underEnumerated.length > 0) {
			deficits.push({
				target: "effort.alternative",
				reason: `decisions under the enumeration floor: ${underEnumerated.map(([d]) => d).join(", ")}`,
			});
		}
		const verifierRuns = Object.values(inputs.metered.verifierRunsByTier).reduce((a, b) => a + b, 0);
		if (verifierRuns < inputs.floors.verifierRunsMin) {
			deficits.push({
				target: "effort.verifier_run",
				reason: `verifier runs ${verifierRuns} < floor ${inputs.floors.verifierRunsMin}`,
			});
		}
		for (const deficit of deficits) {
			assertEvidenceTarget(deficit.target);
			const push = pushForObligation(open[0], deficit.target, deficit.reason);
			if (push !== null) pushes.push(push);
		}
	}

	// 3 · the ceiling caps everything.
	return pushes.slice(0, ceiling);
}

