// ---------------------------------------------------------------------------
// Obligations and premature topic-switch detection
// ---------------------------------------------------------------------------

export interface Obligation {
	readonly id: string;
	readonly phase: string;
	readonly closed: boolean;
}

/** Reconstructs obligation state mechanically from `obligation.open` / `obligation.close` rows. */
export function obligationsFromLedger(ledgerDir: string, phase: string): Obligation[] {
	const status = new Map<string, boolean>();
	const rowsOf = (r: LedgerRow) =>
		(r.event_type === "obligation.open" || r.event_type === "obligation.close") && r.phase === phase;
	for (const row of scanLedger(ledgerDir, rowsOf)) {
		const id = String((row.payload as Record<string, unknown> | null)?.obligation_id ?? "");
		if (id.length === 0) continue;
		status.set(id, row.event_type === "obligation.close");
	}
	return [...status.entries()].map(([id, closed]) => ({ id, phase, closed }));
}

export interface PrematureSwitchFinding {
	readonly premature: boolean;
	readonly unclosedObligations: readonly string[];
}

/**
 * A topic switch out of a phase is PREMATURE exactly when the phase still has unclosed
 * obligations — mechanically, from the ledger, no judgment call.
 */
export function detectPrematureSwitch(ledgerDir: string, phase: string): PrematureSwitchFinding {
	const unclosed = obligationsFromLedger(ledgerDir, phase)
		.filter((o) => !o.closed)
		.map((o) => o.id);
	return { premature: unclosed.length > 0, unclosedObligations: unclosed };
}

/**
 * The correct intervention for a premature switch: RETURN TO THE UNCLOSED OBLIGATIONS, at the
 * turn boundary. Not "think longer" — that kind does not exist in the push vocabulary. Returns
 * null when the switch was not premature: a clean switch gets no intervention at all.
 */
export function interveneOnPrematureSwitch(finding: PrematureSwitchFinding): Push | null {
	if (!finding.premature) return null;
	return {
		kind: "return_to_unclosed_obligations",
		boundary: "turn",
		obligations: finding.unclosedObligations,
		reason:
			`unclosed obligations remain (${finding.unclosedObligations.join(", ")}) — return to them; ` +
			"more thinking time is not the intervention (Axiom 2: pressure lands on boundaries, not inside the loop)",
	};
}

/**
 * Zero pressure on closed obligations: a push can only be built for an OPEN obligation. For a
 * closed one this returns null — there is no error to catch and no pressure to apply; the
 * argumentation obligation is discharged and stays discharged.
 */
export function pushForObligation(obligation: Obligation, target: string, reason: string): Push | null {
	if (obligation.closed) return null;
	return { kind: "evidence_action", boundary: "turn", target, obligations: [obligation.id], reason };
}

