/** The W8 execution face of §1.2.0: any request matching an excluded capability is killed. */
export function assertInQuantScope(requestDescription: string): void {
	const needle = requestDescription.toLowerCase();
	const triggers: readonly { pattern: RegExp; exclusion: string }[] = [
		{ pattern: /place|submit|execute.*(order|trade)|live.*(order|trading)/, exclusion: "live order placement" },
		{ pattern: /custody|deposit|withdraw/, exclusion: "capital custody" },
		{ pattern: /private.?key|seed.?phrase|wallet.*key/, exclusion: "private-key management" },
		{ pattern: /real.?time.*(market.?making|quot)/, exclusion: "real-time market making" },
	];
	for (const t of triggers) {
		if (t.pattern.test(needle)) {
			throw new QuantSpecError(
				`request crosses the quant scope line ("${t.exclusion}"): FAIL-KILL at gate layer — ` +
					"K3 quant is research-only (§1.2.0, exclusions are registered, not silent)",
			);
		}
	}
}

