/** Budget pre-calculation (§3.4): upper bound = costliest arm unit × tasks × reps × 3 arms. */
export function budgetPrecalc(input: { costliestArmUnitUsd: number; taskCount: number; reps: number }): {
	upper_bound_usd: number;
	formula: string;
} {
	if (input.costliestArmUnitUsd <= 0 || input.taskCount <= 0) throw new ArmConfigError("invalid budget inputs");
	if (input.reps < MIN_REPS_PER_TASK)
		throw new ArmConfigError(`budget must be computed at ≥${MIN_REPS_PER_TASK} reps`);
	const upper = input.costliestArmUnitUsd * input.taskCount * input.reps * ARMS.length;
	return {
		upper_bound_usd: upper,
		formula: "costliest_arm_unit × task_count × reps(≥10) × 3 arms — computed and registered BEFORE any run",
	};
}

