}

/** family → submode mapping; extendable by registration, never by agent input. */
export const FAMILY_TO_SUBMODE: Readonly<Record<string, Submode>> = Object.freeze({
	mean_reversion_z: "mean_reversion",
	stat_arb_pairs: "mean_reversion",
	sma_cross: "momentum",
	ts_momentum: "momentum",
	breakout: "momentum",
	cross_venue_spread: "arbitrage",
	triangular: "arbitrage",
