});

export interface ClassificationResult {
	readonly submode: Submode;
	readonly spec: SubmodeSpec;
	/** The agent's proposal, recorded but weightless (same shape as W7's agent_label_ignored). */
	readonly agent_proposal_ignored: string | null;
}

/**
 * Classification is MECHANICALLY derived from task metadata (§1.2.2: 分类由任务元数据机械推导，
 * 不由被评估的 agent 自评). Two hard corrections apply regardless of family:
 * multi-venue tasks can never classify above arbitrage's fidelity demands, and LOB-granularity
 * tasks always land in the weak submode.
 */
export function classifySubmode(meta: QuantTaskMeta): ClassificationResult {
	const base = FAMILY_TO_SUBMODE[meta.strategy_family];
	if (!base) {
		throw new SubmodeError(
			`strategy family "${meta.strategy_family}" is not in FAMILY_TO_SUBMODE — unregistered families do not ` +
				"classify (registration precedes execution; the agent cannot invent a family to pick its verifier)",
		);
	}
	let submode: Submode = base;
	if (meta.data_granularity === "lob")
		submode = "market_making"; // LOB fidelity ⇒ weak, always
	else if (meta.venues > 1 && submode !== "market_making") submode = "arbitrage"; // multi-venue ⇒ ≥ arbitrage demands
	return Object.freeze({
		submode,
		spec: submodeSpec(submode),
		agent_proposal_ignored: meta.agent_proposed_submode ?? null,
	});
}

