export interface InstallK3EffortContractOptions {
	readonly ledger: EventLedger;
	/** Absolute ledger directory (normally `<repoRoot>/k3/ledger`). */
	readonly ledgerDir: string;
	readonly repoRoot?: string;
	/** W1 allowlist; when provided, the install verifies the agent domain cannot write the dir. */
	readonly allowlist?: Allowlist;
	readonly mode: SessionMode;
}

export interface K3EffortInstallation {
	readonly contract: EffortContract;
	readonly pushQueue: BoundaryPushQueue;
}

/**
 * Single installation contract: mode residency check → W1 path-protection + allowlist
 * assertions → W3 breaker-strictness assertion → contract + push queue → `effort.install`
 * ledger row. Like every K3 install, there is no enabled flag and no off switch — and unlike
 * every other K3 install, it REFUSES a daily-QA session outright: daily Q&A never enters
 * project mode and never passes through gates, so mounting the contract there would itself
 * violate the residency clause.
 */
export function installK3EffortContract(options: InstallK3EffortContractOptions): K3EffortInstallation {
	if (!modeRequiresContract(options.mode)) {
		throw new ModeResidencyError(
			`mode "${options.mode}" carries no effort contract: daily Q&A does not enter project mode ` +
				"and does not pass through gates — nothing to install",
		);
	}
	assertLedgerPathProtected(options.ledgerDir, options.repoRoot);
	if (options.allowlist) {
		const decision = options.allowlist.checkPath(options.ledgerDir, "write", options.repoRoot);
		if (decision.allowed) {
			throw new LedgerValidationError(
				`allowlist grants agent-domain write on ${options.ledgerDir}; the effort contract refuses to ` +
					"install until the enforcement surface matches the declaration surface (discipline W5)",
			);
		}
	}
	assertBreakerNotLoosened();
	const contract = new EffortContract({ ledger: options.ledger, ledgerDir: options.ledgerDir, mode: options.mode });
	options.ledger.append({
		event_type: "effort.install",
		actor: { role: "harness" },
		action: "install",
		payload: { mode: options.mode, gated: contract.gated },
		idem_key: null,
	});
	return { contract, pushQueue: new BoundaryPushQueue() };
}

