export interface K3SelectionInstallation {
	readonly zone: CandidateZone;
	readonly suites: EvalSuiteManager;
	readonly promotion: PromotionManager;
}

/**
 * Single installation contract, in order:
 *   1. the FCQ four-subquantity set must have its frozen literal shape (G11 is only as strong
 *      as the quantity it reads);
 *   2. seam W1 — archive/active are deny-write in the static literal AND (when an allowlist is
 *      given) unreachable for the agent domain, otherwise the install is refused;
 *   3. zone / suites / promotion manager over the SAME ledger (seam W2);
 *   4. the install itself is a ledger row (`selection.install`) so "the gate was armed" is a
 *      provable fact, not an assumption (same motivation as `canary.install`, W4).
 * There is no `enabled` flag and no off switch (Decision 1's mandatory clause, applied here).
 */
export function installK3SelectionGate(options: InstallK3SelectionGateOptions): K3SelectionInstallation {
	assertFcqShapeFrozen();
	for (const home of [ARCHIVE_HOME, ACTIVE_HOME]) {
		if (!PROTECTED_DENY_WRITE.some((p) => pathHasPrefix(home, p))) {
			throw new LedgerValidationError(
				`${home} is not covered by PROTECTED_DENY_WRITE (${PROTECTED_DENY_WRITE.join(", ")}); ` +
					`an activation surface the agent can write makes the selection gate ornamental`,
			);
		}
		if (options.allowlist) {
			const decision = options.allowlist.checkPath(home, "write", options.root);
			if (decision.allowed) {
				throw new LedgerValidationError(
					`allowlist grants agent-domain write on ${home}; the selection gate refuses to install ` +
						`until the enforcement surface matches the declaration surface`,
				);
			}
		}
	}
	const zone = new CandidateZone({
		root: options.root,
		ledger: options.ledger,
		phase: options.phase,
		...(options.allowlist === undefined ? {} : { allowlist: options.allowlist }),
		...(options.now === undefined ? {} : { now: options.now }),
	});
	const suites = new EvalSuiteManager({
		ledger: options.ledger,
		phase: options.phase,
		...(options.suiteVersions === undefined ? {} : { suiteVersions: options.suiteVersions }),
	});
	const promotion = new PromotionManager({
		root: options.root,
		ledger: options.ledger,
		phase: options.phase,
		domain: options.domain,
		fcq: options.fcq,
		...(options.snapshots === undefined ? {} : { snapshots: options.snapshots }),
		...(options.now === undefined ? {} : { now: options.now }),
	});
	options.ledger.append({
		event_type: "selection.install",
		actor: { role: "harness" },
		action: "install",
		phase: options.phase,
		payload: {
			domain: options.domain,
			apply_phase_disabled: true,
			promotion_channel: "empirical_selection_gate",
			homes: { archive: ARCHIVE_HOME, active: ACTIVE_HOME },
			snapshots_wired: options.snapshots !== undefined,
		},
		idem_key: null,
	});
	return { zone, suites, promotion };
}

